// HandleUnknownMessage logs the message size and the reason, then continues.
func (UnimplementedHandler) HandleUnknownMessage(ctx context.Context, data []byte, err error) error {
	ctxscope.GetLogger(ctx).Warn(
		"ignoring incoming message",
		"err", err,
		"size_bytes", len(data),
		"reason", "no_matching_message",
	)

	return nil
}

// Dispatch passes message to the handler method for its name.
func Dispatch(ctx context.Context, handler Handler, message ReceivedMessage) error {
	switch message.Name {
	case MessageOperationResponse:
		payload, ok := message.Payload.(OperationResponse)
		if !ok {
			return ctxerrors.Wrapf(commerr.ErrInvalidValue, "%s payload is %T", message.Name, message.Payload)
		}

		if err := handler.HandleOperationResponse(ctx, payload); err != nil {
			return ctxerrors.Wrapf(err, "handle %s", message.Name)
		}

		return nil
	case MessageInstrumentCandleMessage:
		payload, ok := message.Payload.(InstrumentCandleEnvelope)
		if !ok {
			return ctxerrors.Wrapf(commerr.ErrInvalidValue, "%s payload is %T", message.Name, message.Payload)
		}

		if err := handler.HandleInstrumentCandleMessage(ctx, payload); err != nil {
			return ctxerrors.Wrapf(err, "handle %s", message.Name)
		}

		return nil
	case MessageInstrumentMarketStatusMessage:
		payload, ok := message.Payload.(InstrumentMarketStatusEnvelope)
		if !ok {
			return ctxerrors.Wrapf(commerr.ErrInvalidValue, "%s payload is %T", message.Name, message.Payload)
		}

		if err := handler.HandleInstrumentMarketStatusMessage(ctx, payload); err != nil {
			return ctxerrors.Wrapf(err, "handle %s", message.Name)
		}

		return nil
	case MessageInstrumentRateMessage:
		payload, ok := message.Payload.(InstrumentRateEnvelope)
		if !ok {
			return ctxerrors.Wrapf(commerr.ErrInvalidValue, "%s payload is %T", message.Name, message.Payload)
		}

		if err := handler.HandleInstrumentRateMessage(ctx, payload); err != nil {
			return ctxerrors.Wrapf(err, "handle %s", message.Name)
		}

		return nil
	case MessageOrderUpdateMessage:
		payload, ok := message.Payload.(OrderUpdateEnvelope)
		if !ok {
			return ctxerrors.Wrapf(commerr.ErrInvalidValue, "%s payload is %T", message.Name, message.Payload)
		}

		if err := handler.HandleOrderUpdateMessage(ctx, payload); err != nil {
			return ctxerrors.Wrapf(err, "handle %s", message.Name)
		}

		return nil
	case MessagePositionClosedMessage:
		payload, ok := message.Payload.(PositionClosedEnvelope)
		if !ok {
			return ctxerrors.Wrapf(commerr.ErrInvalidValue, "%s payload is %T", message.Name, message.Payload)
		}

		if err := handler.HandlePositionClosedMessage(ctx, payload); err != nil {
			return ctxerrors.Wrapf(err, "handle %s", message.Name)
		}

		return nil
	case MessagePositionOpenedMessage:
		payload, ok := message.Payload.(PositionOpenedEnvelope)
		if !ok {
			return ctxerrors.Wrapf(commerr.ErrInvalidValue, "%s payload is %T", message.Name, message.Payload)
		}

		if err := handler.HandlePositionOpenedMessage(ctx, payload); err != nil {
			return ctxerrors.Wrapf(err, "handle %s", message.Name)
		}

		return nil
	}

	return ctxerrors.Wrapf(asyncapirt.ErrUnknownMessage, "%s", message.Name)
}

// Client sends and receives this API's messages over a transport.
type Client struct {
	transport asyncapirt.Transport
}

// NewClient returns a client that uses transport.
func NewClient(transport asyncapirt.Transport) *Client {
	return &Client{transport: transport}
}

// Close closes the transport.
func (c *Client) Close() error {
	if err := c.transport.Close(); err != nil {
		return ctxerrors.Wrap(err, "close transport")
	}

	return nil
}

// Authenticate validates payload and sends it as a MessageAuthenticateRequest message.
// Client → server. Authenticate the session before subscribing to private topics.
func (c *Client) Authenticate(ctx context.Context, payload AuthenticateEnvelope) error {
	if err := asyncapirt.Send(ctx, c.transport, payload); err != nil {
		return ctxerrors.Wrapf(err, "send %s", MessageAuthenticateRequest)
	}

	return nil
}

// Subscribe validates payload and sends it as a MessageSubscribeRequest message.
// Client → server. Subscribe to one or more topics.
func (c *Client) Subscribe(ctx context.Context, payload SubscribeEnvelope) error {
	if err := asyncapirt.Send(ctx, c.transport, payload); err != nil {
		return ctxerrors.Wrapf(err, "send %s", MessageSubscribeRequest)
	}

	return nil
}

// Unsubscribe validates payload and sends it as a MessageUnsubscribeRequest message.
// Client → server. Stop receiving messages for one or more topics.
func (c *Client) Unsubscribe(ctx context.Context, payload UnsubscribeEnvelope) error {
	if err := asyncapirt.Send(ctx, c.transport, payload); err != nil {
		return ctxerrors.Wrapf(err, "send %s", MessageUnsubscribeRequest)
	}

	return nil
}

